/* Ordinary MVCC: another process properly drops/recreates its own DBI. This
 * process never closes/reuses its existing alias, and old readers stay alive. */
#include "named_refresh_helpers.h"
#include <sys/wait.h>
#include <unistd.h>
static void change(const char *path,int mode){MDB_env *e=open_env(path,MDB_NOTLS);MDB_txn *t=begin(e,0);MDB_dbi old=db(t,"x",0);ok(mdb_drop(t,old,1),"peer deletes its own alias");if(mode==3){MDB_dbi main=db(t,NULL,0);char name[]="x";MDB_val k={sizeof name-(MDB_VERSION_MAJOR<1),name},v=val("ordinary");ok(mdb_put(t,main,&k,&v,0),"peer raw MAIN row");}else{unsigned flags=mode==1?MDB_DUPSORT:mode==2?(MDB_DUPSORT|MDB_DUPFIXED):0;MDB_dbi x=db(t,"x",MDB_CREATE|flags);ok(mdb_set_compare(t,x,bytes_compare),"peer comparator");if(flags&MDB_DUPSORT)ok(mdb_set_dupsort(t,x,bytes_compare),"peer duplicate comparator");put(t,x,"k",mode==2?"BB":"B");}ok(mdb_txn_commit(t),"peer commit");mdb_env_close(e);}
static void scenario_refresh(const char *self,const char *path,int mode){need(!mkdir(path,0700),"refresh mkdir");unsigned original_flags=mode==2?(MDB_DUPSORT|MDB_DUPFIXED):0;MDB_env *e=open_env(path,MDB_NOTLS);MDB_txn *t=begin(e,0);MDB_dbi x=db(t,"x",MDB_CREATE|original_flags);ok(mdb_set_compare(t,x,bytes_compare),"seed comparator");if(original_flags&MDB_DUPSORT)ok(mdb_set_dupsort(t,x,bytes_compare),"seed duplicate comparator");put(t,x,"k","A");ok(mdb_txn_commit(t),"seed commit");MDB_txn *held=begin(e,MDB_RDONLY);MDB_val k=val("k"),v;ok(mdb_get(held,x,&k,&v),"held A read");MDB_val borrowed=v;MDB_cursor *c;ok(mdb_cursor_open(held,x,&c),"held A cursor");ok(mdb_cursor_get(c,&k,&v,MDB_SET),"held A position");fflush(stdout);pid_t p=fork();need(p>=0,"fork ordinary peer");if(!p){char text[16];snprintf(text,sizeof text,"%d",mode);execl(self,self,"--peer",path,text,(char*)NULL);_exit(127);}int status;need(waitpid(p,&status,0)==p&&WIFEXITED(status)&&!WEXITSTATUS(status),"ordinary peer");t=begin(e,MDB_RDONLY);MDB_dbi alias=db(t,"x",0);need(alias==x,"public alias remains");flags(t,x,original_flags,"refresh.flags.before");int rc=mdb_get(t,x,&k,&v);printf("refresh.get=%d",rc);if(!rc)printf(" value=%.*s",(int)v.mv_size,(char*)v.mv_data);putchar('\n');if(mode==1||mode==3)need(rc==MDB_INCOMPATIBLE,"changed flags/raw MAIN incompatible");else need(!rc&&v.mv_size==strlen(mode==2?"BB":"B")&&!memcmp(v.mv_data,mode==2?"BB":"B",v.mv_size),"same flags refresh B");MDB_cursor *newc;ok(mdb_cursor_open(t,x,&newc),"refresh cursor open");rc=mdb_cursor_get(newc,&k,&v,MDB_FIRST);printf("refresh.cursor=%d\n",rc);need((mode==1||mode==3)?rc==MDB_INCOMPATIBLE:rc==0,"refresh actual cursor result");mdb_cursor_close(newc);comparator(t,x);mdb_txn_abort(t);
    if(mode==0||mode==2){t=begin(e,0);MDB_txn *child;ok(mdb_txn_begin(e,t,0,&child),"refresh child begin");put(child,x,"child",mode==2?"CC":"child");ok(mdb_txn_commit(child),"refresh child release");ok(mdb_txn_begin(e,t,0,&child),"refresh abort child begin");put(child,x,"lost",mode==2?"LL":"lost");mdb_txn_abort(child);value(t,x,"lost",NULL,"refresh.child.abort");if(mode==0){MDB_val r=val("r"),data={2,NULL};ok(mdb_put(t,x,&r,&data,MDB_RESERVE),"refresh reserve");memcpy(data.mv_data,"RR",2);value(t,x,"r","RR","refresh.reserve");}ok(mdb_txn_commit(t),"refresh parent commit");t=begin(e,MDB_RDONLY);value(t,x,"child",mode==2?"CC":"child","refresh.canonical");mdb_txn_abort(t);}
    need(borrowed.mv_size==1&&*(char*)borrowed.mv_data=='A',"old borrowed A bytes");ok(mdb_cursor_get(c,&k,&v,MDB_GET_CURRENT),"old A current");need(v.mv_size==1&&*(char*)v.mv_data=='A',"old A cursor bytes");mdb_cursor_close(c);mdb_txn_abort(held);mdb_env_close(e);
    e=open_env(path,MDB_RDONLY|MDB_NOTLS);t=begin(e,MDB_RDONLY);if(mode==3){MDB_dbi absent;need(mdb_dbi_open(t,"x",0,&absent)==MDB_INCOMPATIBLE,"proper reopen raw row incompatible");}else{x=db(t,"x",0);ok(mdb_set_compare(t,x,bytes_compare),"reopen comparator");if(mode==1||mode==2)ok(mdb_set_dupsort(t,x,bytes_compare),"reopen duplicate comparator");flags(t,x,mode==1?MDB_DUPSORT:original_flags,"refresh.reopen.flags");value(t,x,"k",mode==2?"BB":"B","refresh.reopen");}mdb_txn_abort(t);mdb_env_close(e);}
int main(int argc,char **argv){if(argc==4&&!strcmp(argv[1],"--peer")){change(argv[2],atoi(argv[3]));return 0;}if(argc!=2)return 2;need(!mkdir(argv[1],0700)||errno==EEXIST,"refresh root");for(int mode=0;mode<4;mode++){char path[4096];int n=snprintf(path,sizeof path,"%s/mode%d",argv[1],mode);need(n>0&&(size_t)n<sizeof path,"refresh path");printf("scenario=G14-non-PREV-refresh-mode%d\n",mode);scenario_refresh(argv[0],path,mode);}puts("named-refresh-complete journeys=4");return 0;}
